const request = $json ?? {};
const headers = request.headers && typeof request.headers === 'object' ? request.headers : {};
const body = request.body && typeof request.body === 'object' ? request.body : {};
const key = Object.keys(headers).find((item) => String(item).toLowerCase() === 'authorization');
const expected = String($env.N8N_WORKFLOWS_TOKEN || '').trim();
const provided = String(key ? headers[key] : '').replace(/^bearer\s+/i, '').trim();
if (!expected || provided !== expected) return [{json:{ok:false,status_code:401,error:'invalid workflows token'}}];
const expectedEmail = String(body.expected_email || '').trim().toLowerCase();
if (!expectedEmail) return [{json:{ok:false,status_code:400,error:'expected_email is required'}}];
return [{json:{realm:String(body.realm || $env.N8N_REALM || $env.N8N_ENV_REALM || 'aiops'),dry_run:true,expected_email:expectedEmail}}];

const result = $json ?? {};
const admins = Array.isArray(result.effective_admins) ? result.effective_admins : [];
const expectedEmail = String($node['Validate Test Request'].json.expected_email || '').toLowerCase();
const passed = result.ok === true && result.dry_run === true && result.workflow_id === 'wf.gitlab_realm_admin_membership_sync' && admins.some((user) => String(user.email || '').toLowerCase() === expectedEmail);
return [{json:{ok:passed,status_code:passed?200:500,expected_email:expectedEmail,target_response:result,error:passed?null:'effective inherited realm-admin was not detected'}}];
